class View:
    def __init__(self):
        self.rows=[]; self.notes={}; self.loading=False; self.error=None; self.seq=0
        self._current_id = None
    def begin(self, query):
        self.seq += 1
        self._current_id = self.seq
        self.loading = False
        self.error = None
        return self._current_id
    def finish(self, request_id, rows):
        if request_id != self._current_id:
            return False
        self._current_id = None
        self.rows = rows
        return True
    def get_loading(self):
        return self.loading
    def copy_accepted_rows(self):
        # Return a copy of current rows
        return list(self.rows)
    # notes are preserved automatically
